const http = require('node:http');
const https = require('node:https');

const runnerBase = $env.AUTOMATION_RUNNER_BASE_URL;
const runnerToken = $env.AUTOMATION_RUNNER_TOKEN;
if (!runnerBase) throw new Error('AUTOMATION_RUNNER_BASE_URL is not configured');
const headers = {
  'Content-Type': 'application/json',
  ...(runnerToken ? { Authorization: `Bearer ${runnerToken}` } : {}),
};

const request = (urlString, options = {}) => new Promise((resolve, reject) => {
  const transport = String(urlString).startsWith('https://') ? https : http;
  const req = transport.request(urlString, {
    method: options.method || 'GET',
    headers: options.headers || {},
  }, (res) => {
    let body = '';
    res.on('data', (chunk) => {
      body += chunk.toString();
    });
    res.on('end', () => {
      resolve({
        statusCode: res.statusCode || 0,
        body,
      });
    });
  });
  req.on('error', reject);
  if (options.body) {
    req.write(options.body);
  }
  req.end();
});

const parseJson = (value, fallback) => {
  try {
    return value ? JSON.parse(value) : fallback;
  } catch {
    return fallback;
  }
};

const healthResponse = await request(`${runnerBase}/services/health`, { headers });
if (healthResponse.statusCode < 200 || healthResponse.statusCode >= 300) {
  throw new Error(`services/health failed: ${healthResponse.statusCode} ${healthResponse.body}`);
}
const health = parseJson(healthResponse.body, {});

let restartResult = null;
const failingServices = Array.isArray(health.failingServices) ? health.failingServices : [];
const restartTarget = failingServices.find((service) => health.services?.[service]?.restartable);
if (restartTarget) {
  const restartResponse = await request(`${runnerBase}/jobs`, {
    method: 'POST',
    headers,
    body: JSON.stringify({ action: 'restart_service', mode: 'sync', args: [restartTarget] }),
  });
  if (restartResponse.statusCode < 200 || restartResponse.statusCode >= 300) {
    throw new Error(`restart_service failed: ${restartResponse.statusCode} ${restartResponse.body}`);
  }
  restartResult = parseJson(restartResponse.body, null);
}

const reportRelativePath = `health-monitor/${new Date().toISOString().replace(/[:]/g, '-')}.md`;
const reportContent = [
  '# Automation Health Monitor',
  '',
  `Generated: ${new Date().toISOString()}`,
  `Healthy: ${health.ok ? 'yes' : 'no'}`,
  `Restart Target: ${restartTarget || 'none'}`,
  '',
  '## Health Snapshot',
  '',
  '```json',
  JSON.stringify(health, null, 2),
  '```',
  '',
  '## Restart Result',
  '',
  restartResult ? '```json\n' + JSON.stringify(restartResult, null, 2) + '\n```' : 'No restart attempted.',
].join('\n');

const writeResponse = await request(`${runnerBase}/reports/write`, {
  method: 'POST',
  headers,
  body: JSON.stringify({ relativePath: reportRelativePath, content: reportContent }),
});
if (writeResponse.statusCode < 200 || writeResponse.statusCode >= 300) {
  throw new Error(`reports/write failed: ${writeResponse.statusCode} ${writeResponse.body}`);
}

const contextResponse = await request(`${runnerBase}/context/health-monitor`, {
  method: 'PUT',
  headers,
  body: JSON.stringify({ value: { health, restartResult, reportRelativePath } }),
});
if (contextResponse.statusCode < 200 || contextResponse.statusCode >= 300) {
  throw new Error(`context/health-monitor failed: ${contextResponse.statusCode} ${contextResponse.body}`);
}

return [{ json: { generatedAt: new Date().toISOString(), health, restartTarget, restartResult, reportRelativePath } }];
